      backup_text =
        "# HAUNTED TOASTER - A Tamagotchi-style Virtual Pet #\n\
         # Your pet is a possessed kitchen appliance with feelings #\n\n\
         type Stat = Int in  # 0-100 range #\n\n\
         type Stats = (\n\
         hunger = Stat,     # 0 = starving, 100 = stuffed #\n\
         happiness = Stat,  # 0 = miserable, 100 = ecstatic #\n\
         energy = Stat,     # 0 = exhausted, 100 = hyperactive #\n\
         health = Stat      # 0 = broken, 100 = pristine #\n\
         ) in\n\n\
         type Evolution =\n\
         + BabyToaster      # Just possessed, learning the ropes #\n\
         + TeenToaster      # Moody, unpredictable #\n\
         + AdultToaster     # Mature, stable #\n\
         + GoldenToaster    # Legendary, well-cared-for #\n\
         + RustyToaster     # Neglected, cranky #\n\
         in\n\n\
         type Personality =\n\
         + Cheerful\n\
         + Grumpy\n\
         + Anxious\n\
         + Balanced\n\
         in\n\n\
         type Memory = (\n\
         timesFed = Int,\n\
         timesPlayed = Int,\n\
         timesSlept = Int,\n\
         timesNeglected = Int\n\
         ) in\n\n\
         type Model = (\n\
         stats = Stats,\n\
         evolution = Evolution,\n\
         personality = Personality,\n\
         memory = Memory,\n\
         age = Int           # Time ticks elapsed #\n\
         ) in\n\n\
         type Action =\n\
         + Feed              # Reduces hunger, slight energy boost #\n\
         + Play              # Increases happiness, costs energy #\n\
         + Sleep             # Restores energy, slight health boost #\n\
         + Repair            # Fixes health issues #\n\
         + TimeTick          # Time passes, stats decay #\n\
         in\n\n\
         # Utility: clamp value between 0 and 100 #\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         # Initial state: a fresh baby toaster #\n\
         let init: Model = (\n\
         stats = (\n\
         hunger = 50,\n\
         happiness = 50,\n\
         energy = 50,\n\
         health = 100\n\
         ),\n\
         evolution = BabyToaster,\n\
         personality = Balanced,\n\
         memory = (\n\
         timesFed = 0,\n\
         timesPlayed = 0,\n\
         timesSlept = 0,\n\
         timesNeglected = 0\n\
         ),\n\
         age = 0\n\
         ) in\n\n\
         # Calculate stat decay based on current stats and interactions #\n\
         let decayStats : Stats -> Stats =\n\
         fun s ->\n\
         let hungerDecay = 5 in\n\
         let happinessDecay =\n\
         if s.hunger < 30 then 8  # Hungry makes mood worse #\n\
         else 3\n\
         in\n\
         let energyDecay = 2 in\n\
         let healthDecay =\n\
         if s.energy < 20 then 5   # Exhaustion hurts health #\n\
         else if s.hunger < 20 then 3  # Starvation hurts health #\n\
         else 0\n\
         in\n\
         (\n\
         hunger = clamp(s.hunger - hungerDecay),\n\
         happiness = clamp(s.happiness - happinessDecay),\n\
         energy = clamp(s.energy - energyDecay),\n\
         health = clamp(s.health - healthDecay)\n\
         )\n\
         in\n\n\
         # Determine personality based on memory #\n\
         let calcPersonality : Memory -> Personality =\n\
         fun m ->\n\
         let careScore = m.timesFed + m.timesPlayed + m.timesSlept in\n\
         let neglectScore = m.timesNeglected in\n\
         if neglectScore > careScore then Grumpy\n\
         else if m.timesPlayed > m.timesFed + m.timesSlept then Cheerful\n\
         else if m.timesNeglected > 5 then Anxious\n\
         else Balanced\n\
         in\n\n\
         # Determine evolution based on age and care quality #\n\
         let calcEvolution : (Int, Memory) -> Evolution =\n\
         fun (age, m) ->\n\
         let careScore = m.timesFed + m.timesPlayed + m.timesSlept in\n\
         let neglectScore = m.timesNeglected in\n\
         if age < 10 then BabyToaster\n\
         else if age < 25 then TeenToaster\n\
         else if careScore > neglectScore * 3 then GoldenToaster\n\
         else if neglectScore > careScore then RustyToaster\n\
         else AdultToaster\n\
         in\n\n\
         # Check if stats indicate neglect (any stat critically low) #\n\
         let isNeglected : Stats -> Bool =\n\
         fun s ->\n\
         s.hunger < 15 || s.happiness < 15 || s.energy < 10 || s.health < 20\n\
         in\n\n\
         # Update memory based on action #\n\
         let updateMemory : (Memory, Action, Stats) -> Memory =\n\
         fun (m, action, stats) ->\n\
         case action\n\
         | Feed => (m.timesFed + 1, m.timesPlayed, m.timesSlept, \
         m.timesNeglected)\n\
         | Play => (m.timesFed, m.timesPlayed + 1, m.timesSlept, \
         m.timesNeglected)\n\
         | Sleep => (m.timesFed, m.timesPlayed, m.timesSlept + 1, \
         m.timesNeglected)\n\
         | Repair => m\n\
         | TimeTick =>\n\
         if isNeglected(stats)\n\
         then (m.timesFed, m.timesPlayed, m.timesSlept, m.timesNeglected + 1)\n\
         else m\n\
         end\n\
         in\n\n\
         # Apply an action to stats #\n\
         # BUG: Sleep uses (- bonus) instead of (+ bonus) for energy #\n\
         # Cheerful toasters get LESS energy from sleep, grumpy get MORE #\n\
         let applyAction : (Stats, Action, Personality) -> Stats =\n\
         fun (s, action, personality) ->\n\
         # Personality affects action effectiveness #\n\
         let bonus = case personality\n\
         | Cheerful => 5\n\
         | Grumpy => -5\n\
         | Anxious => -2\n\
         | Balanced => 0\n\
         end\n\
         in\n\
         case action\n\
         | Feed =>\n\
         (\n\
         hunger = clamp(s.hunger + 30 + bonus),\n\
         happiness = clamp(s.happiness + 5),\n\
         energy = clamp(s.energy + 10),\n\
         health = s.health\n\
         )\n\
         | Play =>\n\
         if s.energy < 20\n\
         then # Too tired to play effectively #\n\
         (\n\
         hunger = s.hunger,\n\
         happiness = clamp(s.happiness + 5),\n\
         energy = clamp(s.energy - 5),\n\
         health = s.health\n\
         )\n\
         else\n\
         (\n\
         hunger = clamp(s.hunger - 10),\n\
         happiness = clamp(s.happiness + 25 + bonus),\n\
         energy = clamp(s.energy - 15),\n\
         health = s.health\n\
         )\n\
         | Sleep =>\n\
         (\n\
         hunger = clamp(s.hunger - 5),\n\
         happiness = s.happiness,\n\
         energy = clamp(s.energy + 40 - bonus),  # BUG: should be + bonus #\n\
         health = clamp(s.health + 5)\n\
         )\n\
         | Repair =>\n\
         (\n\
         hunger = s.hunger,\n\
         happiness = clamp(s.happiness - 10),  # Repairs are uncomfortable #\n\
         energy = s.energy,\n\
         health = clamp(s.health + 35 + bonus)\n\
         )\n\
         | TimeTick => decayStats(s)\n\
         end\n\
         in\n\n\
         # Main update function #\n\
         let update : (Model, Action) -> Model =\n\
         fun (m, action) ->\n\
         let newStats = applyAction(m.stats, action, m.personality) in\n\
         let newMemory = updateMemory(m.memory, action, m.stats) in\n\
         let newAge = case action\n\
         | TimeTick => m.age + 1\n\
         | _ => m.age\n\
         end\n\
         in\n\
         (\n\
         stats = newStats,\n\
         evolution = calcEvolution(newAge, newMemory),\n\
         personality = calcPersonality(newMemory),\n\
         memory = newMemory,\n\
         age = newAge\n\
         )\n\
         in\n\n\
         # Run multiple actions in sequence #\n\
         let do : (Model, [Action]) -> Model =\n\
         fun (model: Model, actions: [Action]) ->\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         # Generate n TimeTicks (range is inclusive, so use n-1) #\n\
         let timePasses : Int -> [Action] =\n\
         fun n ->\n\
         if n <= 0 then []\n\
         else map(range(1, n), fun _ -> TimeTick)\n\
         in\n\n\
         # Test: Cheerful toaster should get MORE energy from sleep than \
         grumpy #\n\
         hint \"cheerful toaster gets more energy from sleep\"\n\
         test\n\
         let cheerfulModel = (\n\
         stats = (hunger = 50, happiness = 50, energy = 30, health = 50),\n\
         evolution = AdultToaster,\n\
         personality = Cheerful,\n\
         memory = (timesFed = 5, timesPlayed = 10, timesSlept = 2, \
         timesNeglected = 0),\n\
         age = 25\n\
         ) in\n\
         let grumpyModel = (\n\
         stats = (hunger = 50, happiness = 50, energy = 30, health = 50),\n\
         evolution = AdultToaster,\n\
         personality = Grumpy,\n\
         memory = (timesFed = 2, timesPlayed = 2, timesSlept = 2, \
         timesNeglected = 10),\n\
         age = 25\n\
         ) in\n\
         let cheerfulSlept = update(cheerfulModel, Sleep) in\n\
         let grumpySlept = update(grumpyModel, Sleep) in\n\
         # Correct: cheerful gets 40+5=45, grumpy gets 40-5=35 #\n\
         # Buggy: cheerful gets 40-5=35, grumpy gets 40-(-5)=45 #\n\
         cheerfulSlept.stats.energy > grumpySlept.stats.energy\n\
         end;\n\n\
         # Demo run #\n\
         do(init, [Feed, Play, Sleep, TimeTick, TimeTick])\n";
      refractors = "()";
    } )
